<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:13px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{border:1px solid #999;padding:8px;text-align:right}.total{font-weight:bold;background:#eef4ff}</style></head><body><h1 style="text-align:center">تسعيرة خدمات التنويم</h1><table><tr><th>اسم المريض</th><td>{{ $record->patient_name }}</td></tr><tr><th>رقم الملف</th><td>{{ $record->file_number }}</td></tr><tr><th>الجنسية</th><td>{{ $record->nationality_record->name_ar ?? $record->nationality }}</td></tr><tr><th>الغرفة</th><td>{{ $record->room_record->name_ar ?? 'بدون غرفة' }} — {{ number_format((float)($record->calculation['room_price'] ?? $record->room_price ?? 0),2) }}</td></tr><tr><th>الطبيب</th><td>{{ $record->doctor }}</td></tr><tr><th>الأيام</th><td>{{ $record->days }}</td></tr><tr><th>الإجراءات</th><td>{{ $record->procedurs ?: '—' }}</td></tr><tr><th>قيمة الإجراءات</th><td>{{ number_format((float)($record->calculation['procedures_total'] ?? $record->code_total ?? 0),2) }}</td></tr><tr><th>المبلغ قبل الضريبة بعد الخصم</th><td>{{ number_format((float)($record->calculation['after_discount'] ?? 0),2) }}</td></tr><tr><th>الضريبة</th><td>{{ number_format((float)($record->calculation['vat'] ?? 0),2) }}</td></tr><tr class="total"><th>الإجمالي</th><td>{{ number_format((float)($record->calculation['total'] ?? 0),2) }}</td></tr></table>@if($type === 'manual' && $record->manual_procedures->isNotEmpty())<h2>تفاصيل الإجراءات</h2><table><tr><th>الإجراء</th><th>السعر</th></tr>@foreach($record->manual_procedures as $procedure)<tr><td>{{ $procedure->name }}</td><td>{{ number_format((float)$procedure->price,2) }}</td></tr>@endforeach</table>@endif</body></html>
